" 75 :   @Override
 76 :   @SuppressWarnings("fallthrough")
 77 :   public Node optimizeSubtree(Node node) {
 78 :     switch(node.getType()) {
 79 :       case Token.RETURN: {
 80 :         Node result = tryRemoveRedundantExit(node);
 81 :         if (result != node) {
 82 :           return result;
 83 :         }
 84 :         result = tryReplaceExitWithBreak(node);
 85 :         if (result != node) {
 86 :           return result;
 87 :         }
 88 :         return tryReduceReturn(node);
 89 :       }
 90 : 
 91 :       case Token.THROW: {
 92 :         Node result = tryRemoveRedundantExit(node);
 93 :         if (result != node) {
 94 :           return result;
 95 :         }
 96 :         return tryReplaceExitWithBreak(node);
 97 :       }
 98 : 
 99 :       // TODO(johnlenz): Maybe remove redundant BREAK and CONTINUE. Overlaps
100 :       // with MinimizeExitPoints.
101 : 
102 :       case Token.NOT:
103 :         tryMinimizeCondition(node.getFirstChild());
104 :         return tryMinimizeNot(node);
105 : 
106 :       case Token.IF:
107 :         tryMinimizeCondition(node.getFirstChild());
108 :         return tryMinimizeIf(node);
109 : 
110 :       case Token.EXPR_RESULT:
111 :         tryMinimizeCondition(node.getFirstChild());
112 :         return node;
113 : 
114 :       case Token.HOOK:
115 :         tryMinimizeCondition(node.getFirstChild());
116 :         return node;
117 : 
118 :       case Token.WHILE:
119 :       case Token.DO:
120 :         tryMinimizeCondition(NodeUtil.getConditionExpression(node));
121 :         return node;
122 : 
123 :       case Token.FOR:
124 :         if (!NodeUtil.isForIn(node)) {
125 :           tryJoinForCondition(node);
126 :           tryMinimizeCondition(NodeUtil.getConditionExpression(node));
127 :         }
128 :         return node;
129 : 
130 :       case Token.TRUE:
131 :       case Token.FALSE:
132 :         return reduceTrueFalse(node);
133 : 
134 :       case Token.NEW:
135 :         node = tryFoldStandardConstructors(node);
136 :         if (!node.isCall()) {
137 :           return node;
138 :         }
139 :         // Fall through on purpose because tryFoldStandardConstructors() may
140 :         // convert a NEW node into a CALL node
141 :       case Token.CALL:
142 :         Node result =  tryFoldLiteralConstructor(node);
143 :         if (result == node) {
144 :           result = tryFoldSimpleFunctionCall(node);
145 :           if (result == node) {
146 :             result = tryFoldImmediateCallToBoundFunction(node);
147 :           }
148 :         }
149 :         return result;
150 : 
151 :       case Token.COMMA:
152 :         return trySplitComma(node);
153 : 
154 :       case Token.NAME:
155 :         return tryReplaceUndefined(node);
156 : 
157 :       case Token.BLOCK:
158 :         return tryReplaceIf(node);
159 : 
160 :       case Token.ARRAYLIT:
161 :         return tryMinimizeArrayLiteral(node);
162 : 
163 :       default:
164 :         return node; //Nothing changed
165 :     }
