"1126 :   private Node tryMinimizeCondition(Node n) {
1127 :     Node parent = n.getParent();
1128 : 
1129 :     switch (n.getType()) {
1130 :       case Token.NOT:
1131 :         Node first = n.getFirstChild();
1132 :         switch (first.getType()) {
1133 :           case Token.NOT: {
1134 :               Node newRoot = first.removeFirstChild();
1135 :               parent.replaceChild(n, newRoot);
1136 :               reportCodeChange();
1137 :               // No need to traverse, tryMinimizeCondition is called on the
1138 :               // NOT children are handled below.
1139 :               return newRoot;
1140 :             }
1141 :           case Token.AND:
1142 :           case Token.OR: {
1143 :               // !(!x && !y) --> x || y
1144 :               // !(!x || !y) --> x && y
1145 :               // !(!x && y) --> x || !y
1146 :               // !(!x || y) --> x && !y
1147 :               // !(x && !y) --> !x || y
1148 :               // !(x || !y) --> !x && y
1149 :               // !(x && y) --> !x || !y
1150 :               // !(x || y) --> !x && !y
1151 :               Node leftParent = first.getFirstChild();
1152 :               Node rightParent = first.getLastChild();
1153 :               Node left, right;
1154 : 
1155 :               // Check special case when such transformation cannot reduce
1156 :               // due to the added ()
1157 :               // It only occurs when both of expressions are not NOT expressions
1158 :               if (!leftParent.isNot()
1159 :                   && !rightParent.isNot()) {
1160 :                 // If an expression has higher precedence than && or ||,
1161 :                 // but lower precedence than NOT, an additional () is needed
1162 :                 // Thus we do not preceed
1163 :                 int op_precedence = NodeUtil.precedence(first.getType());
1164 :                 if ((isLowerPrecedence(leftParent, NOT_PRECEDENCE)
1165 :                     && isHigherPrecedence(leftParent, op_precedence))
1166 :                     || (isLowerPrecedence(rightParent, NOT_PRECEDENCE)
1167 :                     && isHigherPrecedence(rightParent, op_precedence))) {
1168 :                   return n;
1169 :                 }
1170 :               }
1171 : 
1172 :               if (leftParent.isNot()) {
1173 :                 left = leftParent.removeFirstChild();
1174 :               } else {
1175 :                 leftParent.detachFromParent();
1176 :                 left = IR.not(leftParent).srcref(leftParent);
1177 :               }
1178 :               if (rightParent.isNot()) {
1179 :                 right = rightParent.removeFirstChild();
1180 :               } else {
1181 :                 rightParent.detachFromParent();
1182 :                 right = IR.not(rightParent).srcref(rightParent);
1183 :               }
1184 : 
1185 :               int newOp = (first.isAnd()) ? Token.OR : Token.AND;
1186 :               Node newRoot = new Node(newOp, left, right);
1187 :               parent.replaceChild(n, newRoot);
1188 :               reportCodeChange();
1189 :               // No need to traverse, tryMinimizeCondition is called on the
1190 :               // AND and OR children below.
1191 :               return newRoot;
1192 :             }
1193 : 
1194 :            default:
1195 :              TernaryValue nVal = NodeUtil.getPureBooleanValue(first);
1196 :              if (nVal != TernaryValue.UNKNOWN) {
1197 :                boolean result = nVal.not().toBoolean(true);
1198 :                int equivalentResult = result ? 1 : 0;
1199 :                return maybeReplaceChildWithNumber(n, parent, equivalentResult);
1200 :              }
1201 :         }
1202 :         // No need to traverse, tryMinimizeCondition is called on the NOT
1203 :         // children in the general case in the main post-order traversal.
1204 :         return n;
1205 : 
1206 :       case Token.OR:
1207 :       case Token.AND: {
1208 :         Node left = n.getFirstChild();
1209 :         Node right = n.getLastChild();
1210 : 
1211 :         // Because the expression is in a boolean context minimize
1212 :         // the children, this can't be done in the general case.
1213 :         left = tryMinimizeCondition(left);
1214 :         right = tryMinimizeCondition(right);
1215 : 
1216 :         // Remove useless conditionals
1217 :         // Handle four cases:
1218 :         //   x || false --> x
1219 :         //   x || true  --> true
1220 :         //   x && true --> x
1221 :         //   x && false  --> false
1222 :         TernaryValue rightVal = NodeUtil.getPureBooleanValue(right);
1223 :         if (NodeUtil.getPureBooleanValue(right) != TernaryValue.UNKNOWN) {
1224 :           int type = n.getType();
1225 :           Node replacement = null;
1226 :           boolean rval = rightVal.toBoolean(true);
1227 : 
1228 :           // (x || FALSE) => x
1229 :           // (x && TRUE) => x
1230 :           if (type == Token.OR && !rval ||
1231 :               type == Token.AND && rval) {
1232 :             replacement = left;
1233 :           } else if (!mayHaveSideEffects(left)) {
1234 :             replacement = right;
1235 :           }
1236 : 
1237 :           if (replacement != null) {
1238 :             n.detachChildren();
1239 :             parent.replaceChild(n, replacement);
1240 :             reportCodeChange();
1241 :             return replacement;
1242 :           }
1243 :         }
1244 :         return n;
1245 :       }
1246 : 
1247 :       case Token.HOOK: {
1248 :         Node condition = n.getFirstChild();
1249 :         Node trueNode = n.getFirstChild().getNext();
1250 :         Node falseNode = n.getLastChild();
1251 : 
1252 :         // Because the expression is in a boolean context minimize
1253 :         // the result children, this can't be done in the general case.
1254 :         // The condition is handled in the general case in #optimizeSubtree
1255 :         trueNode = tryMinimizeCondition(trueNode);
1256 :         falseNode = tryMinimizeCondition(falseNode);
1257 : 
1258 :         // Handle four cases:
1259 :         //   x ? true : false --> x
1260 :         //   x ? false : true --> !x
1261 :         //   x ? true : y     --> x || y
1262 :         //   x ? y : false    --> x && y
1263 :         Node replacement = null;
1264 :         TernaryValue trueNodeVal = NodeUtil.getPureBooleanValue(trueNode);
1265 :         TernaryValue falseNodeVal = NodeUtil.getPureBooleanValue(falseNode);
1266 :         if (trueNodeVal == TernaryValue.TRUE
1267 :             && falseNodeVal == TernaryValue.FALSE) {
1268 :           // Remove useless conditionals, keep the condition
1269 :           condition.detachFromParent();
1270 :           replacement = condition;
1271 :         } else if (trueNodeVal == TernaryValue.FALSE
1272 :             && falseNodeVal == TernaryValue.TRUE) {
1273 :           // Remove useless conditionals, keep the condition
1274 :           condition.detachFromParent();
1275 :           replacement = IR.not(condition);
1276 :         } else if (trueNodeVal == TernaryValue.TRUE) {
1277 :           // Remove useless true case.
1278 :           n.detachChildren();
1279 :           replacement = IR.or(condition, falseNode);
1280 :         } else if (falseNodeVal == TernaryValue.FALSE) {
1281 :           // Remove useless false case
1282 :           n.detachChildren();
1283 :           replacement = IR.and(condition, trueNode);
1284 :         }
1285 : 
1286 :         if (replacement != null) {
1287 :           parent.replaceChild(n, replacement);
1288 :           n = replacement;
1289 :           reportCodeChange();
1290 :         }
1291 : 
1292 :         return n;
1293 :       }
1294 : 
1295 :       default:
1296 :         // while(true) --> while(1)
1297 :         TernaryValue nVal = NodeUtil.getPureBooleanValue(n);
1298 :         if (nVal != TernaryValue.UNKNOWN) {
1299 :           boolean result = nVal.toBoolean(true);
1300 :           int equivalentResult = result ? 1 : 0;
1301 :           return maybeReplaceChildWithNumber(n, parent, equivalentResult);
1302 :         }
1303 :         // We can't do anything else currently.
1304 :         return n;
1305 :     }
1306 :   }"

