"415 :   private Node tryReduceReturn(Node n) {
416 :     Node result = n.getFirstChild();
417 : 
418 :     if (result != null) {
419 :       switch (result.getType()) {
420 :         case Token.VOID:
421 :           Node operand = result.getFirstChild();
